CREATE TABLE categories (id INT PRIMARY KEY, parent_id INT NULL, name VARCHAR(50));
INSERT INTO categories VALUES (1,NULL,'Electronics'),(2,1,'Phones'),(3,2,'Android'),(4,2,'iPhone'),(5,1,'Laptops');

WITH RECURSIVE tree AS (
  SELECT id, parent_id, name, CAST(name AS CHAR(500)) AS path, 1 AS depth
  FROM categories WHERE parent_id IS NULL
  UNION ALL
  SELECT c.id, c.parent_id, c.name, CONCAT(t.path, ' > ', c.name), t.depth + 1
  FROM categories c JOIN tree t ON c.parent_id = t.id
)
SELECT id, path, depth FROM tree ORDER BY path;
```
